<section class="app-panel admin-panel admin-card-pad admin-section-space">
  <div class="admin-panel-head"><div><p class="panel-kicker">RETURN QUEUE</p><h2>Customer return requests</h2><p class="admin-muted">Open a return to review its items, approve it, choose restocking and record the refund.</p></div><span class="app-badge status-pill status-neutral"><i></i><?=count($rows)?> SHOWN</span></div>
  <?php if(!$rows):?><div class="admin-empty-state"><strong>No return requests here.</strong><p>New customer return requests will appear in this queue.</p></div>
  <?php else:?><div class="admin-return-directory">
